sc_cat_item_producer.script:
current.event_name = producer.event_name;

current.event_type =
    producer.event_type.toString();

current.technology_tags =
    producer.technology_tags;

current.event_date =
    producer.event_date;

current.registration_deadline =
    producer.registration_deadline;

current.location =
    producer.location;

current.google_maps_link =
    producer.google_maps_link;

current.fees =
    producer.fees;

current.contact_number =
    producer.contact_number;


/* =====================================================
   VENUE AUTHORIZATION DOCUMENT
   ===================================================== */

if (producer.venue_authorization_document) {

    current.venue_authorization_document =
        producer.venue_authorization_document;

}


/* =====================================================
   AUTOMATICALLY FIND LOGGED-IN EVENT ORGANIZER
   ===================================================== */

var organizerGR = new GlideRecord(
    "x_snc_campus_con_0_event_organizers"
);

organizerGR.addQuery(
    "organizer_name",
    gs.getUserID()
);

organizerGR.setLimit(1);

organizerGR.query();


if (organizerGR.next()) {

    /* Store Event Organizer reference */

    current.organizer =
        organizerGR.getUniqueValue();


    /* Save submitted Contact Number
       into Event Organizer */

    if (producer.contact_number) {

        organizerGR.setValue(
            "contact_number",
            producer.contact_number.toString()
        );

        organizerGR.update();

    }

}


/* =====================================================
   EVERY NEW EVENT STARTS AS PENDING
   ===================================================== */

current.verification_status =
    "pending";


/* =====================================================
   RETURN TO EVENT ORGANIZER DASHBOARD
   ===================================================== */

producer.portal_redirect =
    "?id=event_organizer_dashboard";
